package app.morphe.extension.tiktok.feed;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** The picture of the feed screen in the settings, a small JPEG carried in the patch itself. */
final class OledPickerImage {
    private static final String[] PARTS = {
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            ""
    };

    private OledPickerImage() {
    }

    static Bitmap bitmap() {
        StringBuilder all = new StringBuilder();
        for (String part : PARTS) all.append(part);
        byte[] bytes = Base64.decode(all.toString(), Base64.DEFAULT);
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
    }
}
